const DEFAULT_TRACK = "Frontend";
const DEFAULT_LEVEL = "beginner";
const STARTER_PACK_WEEKS = 4;

/**
 * @param {{track?: string, level?: string}} params
 * @returns {{track: string, level: string, steps: string[], estimatedWeeks: number}}
 */
function generateLearningPath({ track, level } = {}) {
  const normalizedTrack = TRACKS[track] ? track : DEFAULT_TRACK;
  const normalizedLevel = level === "intermediate" ? "intermediate" : DEFAULT_LEVEL;

  const steps = TRACKS[normalizedTrack][normalizedLevel];

  return {
    track: normalizedTrack,
    level: normalizedLevel,
    steps,
    // The action list contains five milestones, but the downloadable
    // starter pack itself is organized into four weekly modules.
    estimatedWeeks: STARTER_PACK_WEEKS,
  };
}

function listAvailableTracks() {
  return Object.keys(TRACKS);
}

module.exports = { generateLearningPath, listAvailableTracks };
